from datetime import date, timedelta
from collections.abc import Iterable

def summarize_expiry_status(
    batches: Iterable[dict],
    today: date,
    warning_window_days: int = 3,
) -> dict[str, list[dict]]:
    if warning_window_days < 0:
        raise ValueError("warning_window_days must be non-negative")

    cutoff = today + timedelta(days=warning_window_days)
    status = {"expired": [], "due_soon": [], "available": []}
    for batch in batches:
        quantity = batch["on_hand"]
        if quantity <= 0:
            continue

        expires_on = batch["expires_on"]
        record = {
            "batch_id": batch["batch_id"],
            "quantity": quantity,
            "expires_on": expires_on,
        }
        if expires_on < today:
            status["expired"].append(record)
        elif expires_on <= cutoff:
            status["due_soon"].append(record)
        else:
            status["available"].append(record)

    return status

